<div style="display:flex;justify-content:space-between"><div><h1 class="h">Zakázky</h1><div class="sub">Rozpočet, práce, materiál a zisk na jednom místě.</div></div><a class="btn primary" href="/jobs/new">+ Nová zakázka</a></div>
<div class="grid" style="grid-template-columns:repeat(3,1fr)"><?php foreach($jobs as $j):?><div class="card"><div class="label"><?=View::e($j['status'])?></div><h3><a href="/jobs/<?=$j['id']?>"><?=View::e($j['name'])?></a></h3><div class="sub"><?=View::e($j['company_name'])?></div><div style="display:flex;justify-content:space-between"><span>Rozpočet</span><b><?=View::money($j['budget'])?></b></div><div style="display:flex;justify-content:space-between"><span>Náklady</span><b><?=View::money($j['actual_cost'])?></b></div><?php if((float)$j['actual_cost']>(float)$j['budget'] && (float)$j['budget']>0):?><p class="badge danger">Rozpočet překročen</p><?php endif;?></div><?php endforeach;?></div>
<div class="card" style="margin-top:16px"><h3>Zapsat práci</h3><form class="row" method="post" action="/jobs/hours"><input type="hidden" name="_csrf" value="<?=App\Core\Auth::csrf()?>"><div class="field"><label>Zakázka</label><select name="job_id"><?php foreach($jobs as $j):?><option value="<?=$j['id']?>"><?=View::e($j['name'])?></option><?php endforeach;?></select></div><div class="field"><label>Hodiny</label><input name="hours" type="number" step="0.25" min="0.25" required></div><div class="field"><label>Sazba / hod.</label><input name="rate" type="number" step="0.01"></div><div class="field"><label>Datum</label><input name="work_date" type="date" value="<?=date('Y-m-d')?>"></div><button class="btn primary">Uložit práci</button></form></div>